var DATA = {"claim": "Drug X works", "deps": "trial>randomization|randomization>protocol", "fragility": "High if randomization flawed", "retracted": "randomization"};
console.log("Claim: " + DATA.claim);
// deps like "B>A|C>B|D>C" meaning B depends on A
var edges = DATA.deps.split("|").map(function (s) { return s.trim(); });
var nodes = {}, indeg = {}, adj = {};
edges.forEach(function (e) {
  var p = e.split(">").map(function (s) { return s.trim(); });
  if (p.length !== 2) return;
  var dep = p[0], base = p[1]; // dep depends on base
  nodes[dep] = 1; nodes[base] = 1;
  adj[base] = adj[base] || []; adj[base].push(dep);
  indeg[dep] = (indeg[dep] || 0) + 1; indeg[base] = indeg[base] || 0;
});
// Kahn topological sort (bases first)
var q = Object.keys(nodes).filter(function (n) { return indeg[n] === 0; }), order = [];
while (q.length) { var n = q.shift(); order.push(n); (adj[n] || []).forEach(function (m) { if (--indeg[m] === 0) q.push(m); }); }
console.log("Dependency order (bases first): " + order.join(" -> "));
// retraction impact: everything downstream of the retracted node falls
var bad = {}, stack = [DATA.retracted];
while (stack.length) { var n = stack.pop(); if (bad[n]) continue; bad[n] = 1; (adj[n] || []).forEach(function (m) { stack.push(m); }); }
var impacted = Object.keys(bad);
console.log("RETRACTED: " + DATA.retracted + " -> impacted claims: " + impacted.join(", "));
console.log("Fragility: " + DATA.fragility);
console.log("RESULT: " + impacted.length + " of " + Object.keys(nodes).length + " claims fall with " + DATA.retracted + ".");

